import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import ResumeForm from './components/resume';
import PopUp from './components/Contact'; 
import LoginPage from './components/LoginPage';





function App() {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [userToken, setUserToken] = useState(localStorage.getItem('token') || null);

    // Handle login and save token
    const handleLogin = (token, username) => {
        localStorage.setItem('token', token);
        localStorage.setItem('username', username);
        setUserToken(token);
        console.log('User logged in:', token);
    };

    // Handle logout and remove token
    const handleLogout = () => {
        localStorage.removeItem('token');
        setUserToken(null);
    };

    // Open and close modal functions
    const openModal = () => setIsModalOpen(true);
    const closeModal = () => setIsModalOpen(false);

    return (
        <Router>
            <div className="App">
                {/* Header Section */}
                <header
                    style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        padding: '10px 20px',
                        borderBottom: '1px solid #ddd',
                    }}
                >
                    <h1>Resume Builder</h1>
                    <div>
                        {username && <span style={{ marginRight: '15px' }}>Welcome, {username}</span>}
                        {userToken ? (
                            <button onClick={handleLogout}>Logout</button>
                        ) : (
                            <button
                                onClick={() => navigate('/login')}
                                style={{
                                    backgroundColor: 'blue',
                                    color: 'white',
                                    border: 'none',
                                    padding: '10px 15px',
                                    borderRadius: '5px',
                                    cursor: 'pointer',
                                }}
                            >
                                Login / Sign Up
                            </button>
                        )}
                    </div>
                </header>

                {/* Routes */}
                <Routes>
                    <Route
                        path="/"
                        element={<ResumeForm userToken={userToken} handleLogout={handleLogout} />}
                    />
                    <Route
                        path="/login"
                        element={<LoginPage onLogin={handleLogin} />}
                    />
                </Routes>

                {/* "About Me" Modal */}
                <PopUp isOpen={isModalOpen} onClose={closeModal} title="About Me">
                    <p>Developed by Annie Rome</p>
                    <p>
                        Check out my portfolio here:{" "}
                        <a href="https://www.anniecaroline.com/" target="_blank" rel="noopener noreferrer">
                            My Portfolio
                        </a>
                    </p>
                </PopUp>
            </div>
        </Router>
    );
}

export default App;
